package com.bank.graphql.service;

import com.bank.graphql.model.Transaction;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;

@Service
public class TransactionService {
    public List<Transaction> lastN(String accountNumber, int n) {
        return List.of(
                new Transaction("T1", new BigDecimal("50000"), "CREDIT"),
                new Transaction("T2", new BigDecimal("2500"), "DEBIT"))
                .subList(0, Math.min(n, 2));
    }
}
```

