package com.bank.graphql.service;

import com.bank.graphql.model.Card;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
public class CardService {
    // Batch load: given MANY account numbers, fetch all cards in ONE query.
    // This is what a DataLoader calls to defeat the N+1 problem.
    public Map<String, Card> batchByAccount(Set<String> accountNumbers) {
        return accountNumbers.stream().collect(Collectors.toMap(
                n -> n, n -> new Card("CARD-" + n, new BigDecimal("200000"))));
    }
}
```

```java
// ─── File: src/main/java/com/bank/graphql/resolver/AccountResolver.java ───
package com.bank.graphql.resolver;

import com.bank.graphql.model.*;
import com.bank.graphql.service.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.graphql.data.method.annotation.*;
import org.springframework.stereotype.Controller;
import java.util.List;
import java.util.Set;

// Resolvers map schema fields to data. Each field is fetched only if the
// client asked for it, so there is no over-fetching. One query assembles the
// whole shape, so there is no under-fetching.
@Controller
public class AccountResolver {

    private static final Logger log = LoggerFactory.getLogger(AccountResolver.class);
    private final AccountService accountService;
    private final TransactionService transactionService;
    private final CardService cardService;

    public AccountResolver(AccountService accountService,
                           TransactionService transactionService,
                           CardService cardService) {
        this.accountService = accountService;
        this.transactionService = transactionService;
        this.cardService = cardService;
    }

    // Root query — maps to Query.account(number).
    @QueryMapping
    public Account account(@Argument String number) {
        log.info("GraphQL resolving account {}", number);
        return accountService.findByNumber(number);
    }

    // transactions field — resolved ONLY if the query requested it.
    @SchemaMapping(typeName = "Account", field = "transactions")
    public List<Transaction> transactions(Account account, @Argument int last) {
        return transactionService.lastN(account.getNumber(), last);
    }

    // card field — batched to avoid N+1 when many accounts are queried.
    @SchemaMapping(typeName = "Account", field = "card")
    public Card card(Account account) {
        return cardService.batchByAccount(Set.of(account.getNumber()))
                .get(account.getNumber());
    }
}
```
